// AssertFixtureConformance executes every governed positive and negative fixture.
func AssertFixtureConformance() error {
	for family, fixture := range fixtureSources {
		if err := ValidateDocument(family, []byte(fixture[0])); err != nil {
			return fmt.Errorf("positive fixture %q: %w", family, err)
		}
		if err := ValidateDocument(family, []byte(fixture[1])); err == nil {
			return fmt.Errorf("negative fixture unexpectedly validated: %s", family)
		}
		var err error
		switch family {
		case "agent_definition":
			_, err = DecodeAgentDefinition([]byte(fixture[0]))
		case "agent_policy":
			_, err = DecodeAgentPolicy([]byte(fixture[0]))
		case "agent_run_manifest":
			_, err = DecodeAgentRunManifest([]byte(fixture[0]))
		case "artifact_manifest":
			_, err = DecodeArtifactManifest([]byte(fixture[0]))
		case "batch_receipt":
			_, err = DecodeBatchReceipt([]byte(fixture[0]))
		case "checkpoint_manifest":
			_, err = DecodeCheckpointManifest([]byte(fixture[0]))
		case "compiled_region_manifest":
			_, err = DecodeCompiledRegionManifest([]byte(fixture[0]))
		case "configuration":
			_, err = DecodeConfiguration([]byte(fixture[0]))
		case "dataset_manifest":
			_, err = DecodeDatasetManifest([]byte(fixture[0]))
		case "development_kit_assembly":
			_, err = DecodeDevelopmentKitAssembly([]byte(fixture[0]))
		case "evaluation_snapshot":
			_, err = DecodeEvaluationSnapshot([]byte(fixture[0]))
		case "evidence_manifest":
			_, err = DecodeEvidenceManifest([]byte(fixture[0]))
		case "executable_plan":
			_, err = DecodeExecutablePlan([]byte(fixture[0]))
		case "feature_bundle":
			_, err = DecodeFeatureBundle([]byte(fixture[0]))
		case "feature_contract":
			_, err = DecodeFeatureContract([]byte(fixture[0]))
		case "feature_coverage_manifest":
			_, err = DecodeFeatureCoverageManifest([]byte(fixture[0]))
		case "feature_derivation_receipt":
			_, err = DecodeFeatureDerivationReceipt([]byte(fixture[0]))
		case "feature_manifest":
			_, err = DecodeFeatureManifest([]byte(fixture[0]))
		case "feature_plan":
			_, err = DecodeFeaturePlan([]byte(fixture[0]))
		case "feature_readiness_receipt":
			_, err = DecodeFeatureReadinessReceipt([]byte(fixture[0]))
		case "feature_requirement_set":
			_, err = DecodeFeatureRequirementSet([]byte(fixture[0]))
		case "fit_receipt":
			_, err = DecodeFitReceipt([]byte(fixture[0]))
		case "hardware_topology_manifest":
			_, err = DecodeHardwareTopologyManifest([]byte(fixture[0]))
		case "kernel_qualification":
			_, err = DecodeKernelQualification([]byte(fixture[0]))
		case "lineage_map":
			_, err = DecodeLineageMap([]byte(fixture[0]))
		case "logical_state_schema":
			_, err = DecodeLogicalStateSchema([]byte(fixture[0]))
		case "model_feature_view":
			_, err = DecodeModelFeatureView([]byte(fixture[0]))
		case "model_manifest":
			_, err = DecodeModelManifest([]byte(fixture[0]))
		case "provider_manifest":
			_, err = DecodeProviderManifest([]byte(fixture[0]))
		case "release_manifest":
			_, err = DecodeReleaseManifest([]byte(fixture[0]))
		case "step_capsule":
			_, err = DecodeStepCapsule([]byte(fixture[0]))
		case "study_manifest":
			_, err = DecodeStudyManifest([]byte(fixture[0]))
		case "tool_contract":
			_, err = DecodeToolContract([]byte(fixture[0]))
		case "training_dataset_manifest":
			_, err = DecodeTrainingDatasetManifest([]byte(fixture[0]))
		case "training_phase_graph":
			_, err = DecodeTrainingPhaseGraph([]byte(fixture[0]))
		case "training_recipe":
			_, err = DecodeTrainingRecipe([]byte(fixture[0]))
		case "training_run_manifest":
			_, err = DecodeTrainingRunManifest([]byte(fixture[0]))
		case "transform_execution_plan":
			_, err = DecodeTransformExecutionPlan([]byte(fixture[0]))
		case "transform_graph":
			_, err = DecodeTransformGraph([]byte(fixture[0]))
		case "transform_receipt":
			_, err = DecodeTransformReceipt([]byte(fixture[0]))
		case "transform_spec":
			_, err = DecodeTransformSpec([]byte(fixture[0]))
		case "transform_state_artifact":
			_, err = DecodeTransformStateArtifact([]byte(fixture[0]))
		case "workflow_definition":
			_, err = DecodeWorkflowDefinition([]byte(fixture[0]))
		default:
			return fmt.Errorf("fixture has no generated binding: %s", family)
		}
		if err != nil {
			return fmt.Errorf("typed fixture %q: %w", family, err)
		}
	}
	return nil
}
